-- team run yards a play by season: spread across the 32 clubs
rsql with t as (select season, team, 1.0*yards/plays ypp, plays from log_team_situations where level='nfl' and key='o|kind|run' and plays > 100) select season, count(*) n, round(avg(ypp),3) mean, round(min(ypp),2) mn, round(max(ypp),2) mx, round(sqrt(avg(ypp*ypp)-avg(ypp)*avg(ypp)),3) sd from t group by season order by season
-- top-8 RB seasons by carries: ypc by season
rsql with ps as (select s.year, s.stats__rush r, s.stats__rush_yds y from people__pro__seasons s union all select s.year, s.stats__rush, s.stats__rush_yds from alumni__pro__seasons s) select year, count(*) backs, round(avg(1.0*y/r),3) ypc_backs_150plus, round(max(1.0*y/r),2) best from ps where year between 2025 and 2035 and r >= 150 group by year order by year
-- run blocks: win share on run plays by season (blocks tuple 4th field)
rsql select lp.season, count(*) blocks, round(avg(json_extract(b.value,'$[3]')),4) won_share, round(avg(json_extract(b.value,'$[4]')),3) margin from log_plays lp, json_each(more('log_plays', lp._more), '$.plays') j, json_each(j.value, '$.blocks') b where lp.stream = 'nfl' and json_extract(j.value,'$.kind') = 'Run' group by lp.season order by lp.season
-- carriers on run plays: share by carrier overall bucket? tackles per run and missed tackles per run by season
rsql select lp.season, round(avg(json_array_length(j.value,'$.tacklers')),3) tacklers, round(avg(json_array_length(j.value,'$.missed_tackles')),4) missed, round(avg(json_extract(j.value,'$.top_speed[1]')),3) top_speed from log_plays lp, json_each(more('log_plays', lp._more), '$.plays') j where lp.stream = 'nfl' and json_extract(j.value,'$.kind') = 'Run' group by lp.season order by lp.season
